from pathlib import Path
import json,base64
R=Path(__file__).resolve().parents[2];O=R/'renders/soleil_spring_v1';V=R/'renders/references_calques_v2'
def uri(p):return 'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()
def seq(p,n):return [uri(p/f'{i:02}.png') for i in range(n)]
d={'sun':seq(O/'soleil/frames',64),'clouds':{m:uri(O/'nuages'/f'{m}_overlay.png') for m in ['jour','coucher','nuit']},'spring':uri(O/'spring/01_decor.png'),'cycle3':seq(O/'spring/02_cycle_3',3),'cycle13':seq(O/'spring/03_cycle_13',13),'reference':uri(R/'source/soleil_spring_v1/references/halcyon_reference.png'),'sky':{m:uri(V/'fonds'/m/'01_ciel.png') for m in ['jour','coucher','nuit']},'sea':{m:uri(V/'fonds'/m/'05_mer.png') for m in ['jour','coucher','nuit']},'terrain':{m:uri(V/'falaises/01'/f'calque_{m}.png') for m in ['jour','nuit']},'stars':seq(V/'etoiles',64),'moon':uri(V/'astres/lune.png'),'halo':seq(V/'astres/halo',64),'reflection':{k:seq(V/'reflets'/k/'frames',64) for k in ['soleil','lune']}}
h='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Soleil & Luminous Spring</title><style>*{box-sizing:border-box}body{background:#101d23;color:#e4f2ef;font:16px system-ui;margin:0}header,main,footer{max-width:1220px;margin:auto;padding:24px}header{border-bottom:1px solid #34524f}h1{font-size:28px;margin:7px 0}p{color:#b2ccc8;line-height:1.6}.eyebrow{color:#80ded1;letter-spacing:2px;font-size:12px}button,select{background:#243d45;color:#efffff;padding:11px;border:1px solid #577974;border-radius:6px;cursor:pointer}.bar{display:flex;gap:10px;flex-wrap:wrap;margin:15px 0}.work{display:grid;grid-template-columns:1fr 235px;gap:20px}canvas{width:100%;image-rendering:pixelated;background:#203439}aside{background:#1b3037;padding:16px;border-radius:8px}label{display:block;margin:13px 0}small{color:#b4c9c5}footer{border-top:1px solid #34524f}a{color:#8ae4d5}@media(max-width:800px){.work{grid-template-columns:1fr}}</style><header><div class="eyebrow">CALQUES ANIMÉS / NOUVELLE VARIANTE</div><h1>Soleil subtil & Luminous Spring</h1><p>Le soleil conserve un disque stable ; sa couronne varie doucement. Les grands nuages passent devant les astres. La clairière conserve le bassin, les cascades et les phases originales de la carte Halcyon.</p></header><main><div class="bar"><select id="scene"><option value="cote">Côte · soleil et grands nuages</option><option value="spring" selected>Luminous Spring · nouvelle variante</option><option value="reference">Luminous Spring · référence fixe Halcyon</option></select><select id="mode"><option value="jour">Jour</option><option value="coucher" selected>Coucher</option><option value="nuit">Nuit</option></select><button id="pause">Pause</button><button id="reset">Recommencer</button><button id="png">Exporter PNG</button></div><div class="work"><section><canvas id="view" width="600" height="600"></canvas><p id="clock"></p></section><aside><b>Calques visibles</b><div id="controls"></div><hr><label>Position des nuages<input id="cloudpos" type="range" min="0" max="959" value="0"></label><small>Wrap de 960 px à −8 px/s : 120 s. Position indépendante des 64 phases lumineuses.</small></aside></div><p id="note"></p></main><footer><p>Halcyon : Palikadude / carte <code>luminous_spring.rsground</code>. Graphismes de base : PMDCollab / RawAsset. Décor périphérique : nouvelle génération guidée par la carte. Pas de prétention d’auteur Palika pour les nouveaux éléments, ni de validation native PMDO.</p><small>PNG individuels et planches dans renders/soleil_spring_v1/. Le cycle du Spring est de 6,5 s (3 et 13 images à 10 ticks / 60 Hz), celui du soleil de 5,12 s.</small></footer><script>const DATA=__DATA__;function convert(v){if(typeof v==='string'){let i=new Image();i.src=v;return i}if(Array.isArray(v))return v.map(convert);return Object.fromEntries(Object.entries(v).map(([k,x])=>[k,convert(x)]))}const I=convert(DATA);let scene='spring',mode='coucher',time=0,last=null,run=true,cloudShift=0;const visible={base:true,stars:true,astre:true,cloud:true,sea:true,reflection:true,cliff:true,cycle3:true,cycle13:true},names={base:'Ciel / décor fixe',stars:'Étoiles',astre:'Soleil / lune et halo',cloud:'Grands nuages overlay',sea:'Mer',reflection:'Reflet',cliff:'Falaise',cycle3:'Spring · cycle 3 phases',cycle13:'Spring · cycle 13 phases'},c=document.getElementById('view'),ctx=c.getContext('2d');for(const [k,n]of Object.entries(names)){const l=document.createElement('label'),i=document.createElement('input');i.type='checkbox';i.checked=true;i.onchange=()=>visible[k]=i.checked;l.append(i,document.createTextNode(' '+n));document.getElementById('controls').append(l)}document.getElementById('scene').onchange=e=>{scene=e.target.value;c.width=scene==='cote'?960:600;c.height=600};document.getElementById('mode').onchange=e=>mode=e.target.value;document.getElementById('pause').onclick=e=>{run=!run;e.target.textContent=run?'Pause':'Reprendre'};document.getElementById('reset').onclick=()=>{time=0;cloudShift=0;document.getElementById('cloudpos').value=0};document.getElementById('cloudpos').oninput=e=>cloudShift=Number(e.target.value);document.getElementById('png').onclick=()=>{const a=document.createElement('a');a.href=c.toDataURL();a.download=scene+'_'+mode+'.png';a.click()};function draw(im,x=0,y=0){if(im.complete&&im.naturalWidth)ctx.drawImage(im,x,y)}function frame(t){if(last!==null&&run)time+=t-last;last=t;ctx.clearRect(0,0,c.width,600);let f=Math.floor(time/80)%64,q=Math.floor(time*60/10000)%39;if(scene==='reference'){draw(I.reference);document.getElementById('note').textContent='Carte de référence fixe reconstruite depuis le fichier Halcyon et les feuilles RawAsset.'}else if(scene==='spring'){if(visible.base)draw(I.spring);if(visible.cycle3)draw(I.cycle3[q%3]);if(visible.cycle13)draw(I.cycle13[q%13]);document.getElementById('note').textContent='Nouveau pourtour végétal généré. Bassin et cellules animées conservés pixel pour pixel dans la zone native protégée.'}else{if(visible.base)draw(I.sky[mode]);if(visible.stars&&mode!=='jour')draw(I.stars[f]);if(visible.astre){if(mode==='nuit'){draw(I.halo[f]);draw(I.moon)}else draw(I.sun[f],702,212)}if(visible.cloud){const x=((cloudShift-Math.floor(time*.008))%960+960)%960;draw(I.clouds[mode],x);draw(I.clouds[mode],x-960)}if(visible.sea)draw(I.sea[mode]);if(visible.reflection)draw(I.reflection[mode==='nuit'?'lune':'soleil'][f],674,281);if(visible.cliff)draw(I.terrain[mode==='nuit'?'nuit':'jour']);document.getElementById('note').textContent='Soleil : 8 clés générées, disque verrouillé, variation réduite et 64 phases interpolées. Nuages dessinés APRÈS les astres pour passer devant eux.'}document.getElementById('clock').textContent=scene==='cote'?'Soleil : '+(f+1)+'/64 · nuages : wrap 120 s':'Spring : '+(q+1)+'/39 · cycles '+(q%3+1)+'/3 et '+(q%13+1)+'/13';requestAnimationFrame(frame)}requestAnimationFrame(frame);</script></html>'''
(R/'apercu_soleil_spring_v1.html').write_text(h.replace('__DATA__',json.dumps(d)),encoding='utf8');print('Gallery generated')
